<?php
$title='Statistik';
$dutyMetric=['from'=>$from,'to'=>$to];if($eventTypeId)$dutyMetric['event_type_id']=$eventTypeId;
$reportMetric=['from'=>$from,'to'=>$to];if($reportTypeId)$reportMetric['type_id']=$reportTypeId;
$eventUrls=[];foreach($events as $row){$params=['from'=>$from,'to'=>$to];if((int)($row['event_type_id']??0)>0)$params['event_type_id']=(int)$row['event_type_id'];else $params['automatic']=1;$eventUrls[]=url('dutybook/search?'.http_build_query($params));}
$reportUrls=[];foreach($reportTypes as $row)$reportUrls[]=url('special-reports/search?'.http_build_query(['from'=>$from,'to'=>$to,'type_id'=>(int)$row['type_id']]));
$timelineUrls=[];foreach($timeline as $row){$params=['day'=>$row['day']];if($eventTypeId)$params['event_type_id']=$eventTypeId;if($reportTypeId)$params['report_type_id']=$reportTypeId;$timelineUrls[]=url('statistics/drilldown?'.http_build_query($params));}
?>
